  output [63:0] io_rd,
  output [9:0]  io_csr_vl,
  output [2:0]  io_csr_vlmul,
                io_csr_vsew,
  output        io_csr_ma,
                io_csr_ta
);

  reg  [9:0]  vcsr_regs_vl;
  reg  [2:0]  vcsr_regs_vlmul;
  reg  [2:0]  vcsr_regs_vsew;
  reg         vcsr_regs_ma;
  reg         vcsr_regs_ta;
  wire        is_vsetvl = io_instr[31:25] == 7'h40 & (&(io_instr[14:12]));
  wire [2:0]  new_vtype_vlmul = is_vsetvl ? io_rs2[2:0] : io_instr[22:20];
  wire [2:0]  new_vtype_vsew = is_vsetvl ? io_rs2[5:3] : io_instr[25:23];
  wire [63:0] avl =
    (&(io_instr[31:30])) & (&(io_instr[14:12]))
      ? {59'h0, io_instr[19:15]}
      : ~(io_instr[31]) & (&(io_instr[14:12])) | is_vsetvl
          ? (io_instr[19:15] == 5'h0
               ? (io_instr[11:7] == 5'h0 ? {54'h0, vcsr_regs_vl} : 64'hFFFFFFFFFFFFFFFF)
               : io_rs1)
          : 64'h0;
