  wire [12:0] _vlmax_T_2 = {3'h0, vlen_div_sew} << new_vtype_vlmul[1:0];
  wire [63:0] _GEN =
    {54'h0,
     new_vtype_vlmul[2]
       ? vlen_div_sew
         >> (new_vtype_vlmul == 3'h5
               ? 2'h3
               : new_vtype_vlmul == 3'h6 ? 2'h2 : {1'h0, &new_vtype_vlmul})
       : _vlmax_T_2[9:0]};
