    if (reset) begin
      vcsr_regs_vl <= 10'h0;
      vcsr_regs_vlmul <= 3'h0;
      vcsr_regs_vsew <= 3'h0;
      vcsr_regs_ma <= 1'h0;
      vcsr_regs_ta <= 1'h0;
    end
    else if (io_isConfig) begin
      vcsr_regs_vl <= new_vl[9:0];
      vcsr_regs_vlmul <= new_vtype_vlmul;
      vcsr_regs_vsew <= new_vtype_vsew;
      vcsr_regs_ma <= is_vsetvl ? io_rs2[7] : io_instr[27];
      vcsr_regs_ta <= is_vsetvl ? io_rs2[6] : io_instr[26];
    end
