  assign io_rd = io_isConfig ? new_vl : 64'h0;
  assign io_csr_vl = vcsr_regs_vl;
  assign io_csr_vlmul = vcsr_regs_vlmul;
  assign io_csr_vsew = vcsr_regs_vsew;
  assign io_csr_ma = vcsr_regs_ma;
  assign io_csr_ta = vcsr_regs_ta;
endmodule

