module ExpdLen(
  input  [4:0] io_in_ctrl_lsrc_0,
               io_in_ctrl_lsrc_1,
  input  [5:0] io_in_ctrl_funct6,
  input  [2:0] io_in_ctrl_funct3,
  input        io_in_ctrl_load,
               io_in_ctrl_store,
               io_in_ctrl_alu,
               io_in_ctrl_redu,
               io_in_ctrl_mask,
               io_in_ctrl_widen,
               io_in_ctrl_widen2,
               io_in_ctrl_narrow,
  input  [9:0] io_in_csr_vl,
  input  [2:0] io_in_csr_vlmul,
               io_in_csr_vsew,
  input  [3:0] io_in_emulVd,
               io_in_emulVs2,
  output [3:0] io_out_expdLen,
  output       io_out_ldstCtrl_unitStride,
               io_out_ldstCtrl_mask,
               io_out_ldstCtrl_strided,
               io_out_ldstCtrl_indexed,
               io_out_ldstCtrl_fof,
               io_out_ldstCtrl_segment,
               io_out_ldstCtrl_wholeReg,
  output [2:0] io_out_indexEew,
  output       io_out_gather16,
  output [3:0] io_out_expdLen_indexVd
);

  wire            ldstCtrl_wholeReg;
  wire [3:0][6:0] _GEN = '{7'h8, 7'h10, 7'h20, 7'h40};
  wire            lmul_y0 =
    ~(io_in_csr_vlmul[1]) & ~(io_in_csr_vlmul[0]) | io_in_csr_vlmul[2];
  wire            lmul_y1 =
    ~(io_in_csr_vlmul[2]) & ~(io_in_csr_vlmul[1]) & io_in_csr_vlmul[0];
  wire            lmul_y2 =
    ~(io_in_csr_vlmul[2]) & io_in_csr_vlmul[1] & ~(io_in_csr_vlmul[0]);
  wire            lmul_y3 =
    ~(io_in_csr_vlmul[2]) & io_in_csr_vlmul[1] & io_in_csr_vlmul[0];
  wire            ldstCtrl_unitStride = io_in_ctrl_funct6[1:0] == 2'h0;
  wire            ldstCtrl_mask = io_in_ctrl_lsrc_1 == 5'hB & ldstCtrl_unitStride;
  wire            ldstCtrl_segment = (|(io_in_ctrl_funct6[5:3])) & ~ldstCtrl_wholeReg;
  assign ldstCtrl_wholeReg = io_in_ctrl_lsrc_1 == 5'h8 & ldstCtrl_unitStride;
  wire [3:0]      expdLen_ldst =
    ldstCtrl_wholeReg | ~(io_in_ctrl_funct6[0] & io_in_emulVs2 > io_in_emulVd)
      ? io_in_emulVd
      : io_in_emulVs2;
  wire [3:0]      _expdLen_segVd_T =
    {lmul_y3, lmul_y2, lmul_y1, lmul_y0} * ({1'h0, io_in_ctrl_funct6[5:3]} + 4'h1);
  wire            _indexedElemsPerUop_T_21 = io_in_csr_vsew == 3'h1;
  wire            _indexedElemsPerUop_T_23 = io_in_csr_vsew == 3'h2;
  wire            _indexedElemsPerUop_T_25 = io_in_csr_vsew == 3'h3;
  wire [9:0]      _GEN_0 =
    {3'h0,
     (_indexedElemsPerUop_T_25
        ? 7'h8
        : _indexedElemsPerUop_T_23
            ? 7'h10
            : _indexedElemsPerUop_T_21 ? 7'h20 : 7'h40) < _GEN[io_in_ctrl_funct3[1:0]]
       ? (_indexedElemsPerUop_T_25
            ? 7'h8
            : _indexedElemsPerUop_T_23 ? 7'h10 : _indexedElemsPerUop_T_21 ? 7'h20 : 7'h40)
       : _GEN[io_in_ctrl_funct3[1:0]]};
  wire [9:0]      _indexedExpdLen_T_7 = io_in_csr_vl + _GEN_0;
  wire [9:0]      _indexedExpdLen_T_11 = (_indexedExpdLen_T_7 - 10'h1) / _GEN_0;
  wire            gather16 = io_in_ctrl_funct6 == 6'hE & io_in_ctrl_funct3 == 3'h0;
  wire            _GEN_1 = io_in_ctrl_load | io_in_ctrl_store;
  assign io_out_expdLen =
    _GEN_1 & ~ldstCtrl_mask
      ? (ldstCtrl_segment
           ? (_expdLen_segVd_T > io_in_emulVs2 ? _expdLen_segVd_T : io_in_emulVs2)
           : io_in_ctrl_funct6[0]
               ? (io_in_csr_vl == 10'h0
                    ? 4'h1
                    : (_indexedExpdLen_T_7 - 10'h1) / _GEN_0 < {6'h0, expdLen_ldst}
                        ? _indexedExpdLen_T_11[3:0]
                        : expdLen_ldst)
               : expdLen_ldst)
      : ldstCtrl_mask & _GEN_1 | io_in_ctrl_alu
        & io_in_ctrl_funct3[0] != io_in_ctrl_funct3[1] & io_in_ctrl_funct6 == 6'h10
        | io_in_ctrl_mask & ~(io_in_ctrl_funct6[3:2] == 2'h1 & io_in_ctrl_lsrc_0[4])
          ? 4'h1
          : io_in_ctrl_widen & ~io_in_ctrl_redu | io_in_ctrl_widen2 | io_in_ctrl_narrow
            | gather16 & io_in_csr_vsew == 3'h0
              ? (io_in_csr_vlmul[2] ? 4'h1 : {lmul_y2, lmul_y1, lmul_y0, 1'h0})
              : io_in_ctrl_funct6 == 6'h27 & io_in_ctrl_funct3 == 3'h3
                  ? {1'h0, io_in_ctrl_lsrc_0[2:0]} + 4'h1
                  : {lmul_y3, lmul_y2, lmul_y1, lmul_y0};
  assign io_out_ldstCtrl_unitStride = ldstCtrl_unitStride;
  assign io_out_ldstCtrl_mask = ldstCtrl_mask;
  assign io_out_ldstCtrl_strided = io_in_ctrl_funct6[1:0] == 2'h2;
  assign io_out_ldstCtrl_indexed = io_in_ctrl_funct6[0];
  assign io_out_ldstCtrl_fof = io_in_ctrl_lsrc_1 == 5'h10 & ldstCtrl_unitStride;
  assign io_out_ldstCtrl_segment = ldstCtrl_segment;
  assign io_out_ldstCtrl_wholeReg = ldstCtrl_wholeReg;
  assign io_out_indexEew = {1'h0, io_in_ctrl_funct3[1:0]};
  assign io_out_gather16 = gather16;
  assign io_out_expdLen_indexVd = ldstCtrl_segment ? _expdLen_segVd_T : io_in_emulVd;
endmodule

