module ShiftRightJam(
  input  [13:0] io_in,
  input  [3:0]  io_shamt,
  output [13:0] io_out,
  output        io_sticky
);

  wire [15:0] _sticky_mask_T = 16'h1 << io_shamt;
  assign io_out = (&io_shamt) ? 14'h0 : io_in >> io_shamt;
  assign io_sticky = |(io_in & (_sticky_mask_T[13:0] - 14'h1 | {14{&io_shamt}}));
endmodule

module FAdd_extSig(
  input         clock,
                reset,
                io_valid_in,
                io_is_fp16,
                io_a_sign,
  input  [7:0]  io_a_exp,
  input  [13:0] io_a_sig,
  input         io_b_sign,
  input  [7:0]  io_b_exp,
  input  [13:0] io_b_sig,
  input         io_a_is_posInf,
                io_b_is_posInf,
                io_a_is_negInf,
                io_b_is_negInf,
                io_a_is_nan,
                io_b_is_nan,
  output        io_res_sign,
  output [7:0]  io_res_exp,
  output [14:0] io_res_sig,
  output        io_res_is_posInf,
                io_res_is_negInf,
                io_res_is_nan,
                io_valid_out
);

  wire [13:0] _shiftRight_out_shiftRight_res_shiftRightJam_io_out;
  wire        _shiftRight_out_shiftRight_res_shiftRightJam_io_sticky;
  wire [8:0]  _GEN = {1'h0, io_a_exp};
  wire [8:0]  _GEN_0 = {1'h0, io_b_exp};
  wire [8:0]  exp_diff_a_minus_b = _GEN - _GEN_0;
  wire [8:0]  exp_diff_b_minus_a = _GEN_0 - _GEN;
  wire        a_dominates = ~(exp_diff_a_minus_b[8]) & (|(exp_diff_a_minus_b[8:4]));
  wire        b_dominates = ~(exp_diff_b_minus_a[8]) & (|(exp_diff_b_minus_a[8:4]));
  reg         io_valid_out_REG;
  reg         is_fp16_S1;
  reg  [7:0]  a_in_S1_exp;
  reg  [13:0] a_in_S1_sig;
  reg  [7:0]  b_in_S1_exp;
  reg  [13:0] b_in_S1_sig;
  reg         sign_a_S1;
  reg         sign_b_S1;
  reg  [7:0]  exp_a_S1;
  reg  [7:0]  exp_b_S1;
  reg         abs_a_gt_b_S1;
  reg  [13:0] adderIn_a_S1_r;
  reg  [13:0] adderIn_b_S1_r;
  reg         exp_a_gte_b_S1;
  wire        a_b_diffSign = sign_a_S1 & ~sign_b_S1 | ~sign_a_S1 & sign_b_S1;
  wire [15:0] _adderOut_temp_T_2 =
    {a_b_diffSign & ~abs_a_gt_b_S1 ? {1'h1, ~adderIn_a_S1_r} : {1'h0, adderIn_a_S1_r},
     a_b_diffSign}
    + {a_b_diffSign & abs_a_gt_b_S1 ? {1'h1, ~adderIn_b_S1_r} : {1'h0, adderIn_b_S1_r},
       a_b_diffSign};
  wire        sign_adderOut =
    a_b_diffSign ? (abs_a_gt_b_S1 ? sign_a_S1 : sign_b_S1) : sign_a_S1 & sign_b_S1;
  wire [7:0]  exp_adderOut = exp_a_gte_b_S1 ? exp_a_S1 : exp_b_S1;
  wire        isExactZero =
    a_b_diffSign & a_in_S1_exp == b_in_S1_exp & a_in_S1_sig == b_in_S1_sig;
  wire [7:0]  _exp_adderOut_over_1_T = exp_adderOut - 8'h1;
  wire [7:0]  _lzd_adderOut_T_11 =
    {4'h0, _adderOut_temp_T_2[7:4]} | {_adderOut_temp_T_2[3:1], 5'h10};
  wire [7:0]  _lzd_adderOut_T_21 =
    {2'h0, _lzd_adderOut_T_11[7:2] & 6'h33} | {_lzd_adderOut_T_11[5:0] & 6'h33, 2'h0};
  wire [6:0]  _lzd_adderOut_T_31 =
    _lzd_adderOut_T_21[7:1] & 7'h55 | {1'h0, _lzd_adderOut_T_21[4:0] & 5'h15, 1'h0};
  wire [3:0]  lzd_adderOut =
    _adderOut_temp_T_2[13]
      ? 4'h0
      : _adderOut_temp_T_2[12]
          ? 4'h1
          : _adderOut_temp_T_2[11]
              ? 4'h2
              : _adderOut_temp_T_2[10]
                  ? 4'h3
                  : _adderOut_temp_T_2[9]
                      ? 4'h4
                      : _adderOut_temp_T_2[8]
                          ? 4'h5
                          : _lzd_adderOut_T_31[0]
                              ? 4'h6
                              : _lzd_adderOut_T_31[1]
                                  ? 4'h7
                                  : _lzd_adderOut_T_31[2]
                                      ? 4'h8
                                      : _lzd_adderOut_T_31[3]
                                          ? 4'h9
                                          : _lzd_adderOut_T_31[4]
                                              ? 4'hA
                                              : _lzd_adderOut_T_31[5]
                                                  ? 4'hB
                                                  : {3'h6, ~(_lzd_adderOut_T_31[6])};
  wire        _GEN_1 = _exp_adderOut_over_1_T <= {4'h0, lzd_adderOut};
  wire        adderOut_is_inf =
    _adderOut_temp_T_2[15] & exp_adderOut == (is_fp16_S1 ? 8'h1E : 8'hFE);
  wire [29:0] _sig_adderOut_shifted_T =
    {15'h0, _adderOut_temp_T_2[15:1]}
    << (_adderOut_temp_T_2[15]
          ? 4'h0
          : _adderOut_temp_T_2[14]
              ? 4'h1
              : _GEN_1 ? _exp_adderOut_over_1_T[3:0] + 4'h1 : lzd_adderOut + 4'h2);
  wire        _GEN_2 =
    isExactZero | ~(_adderOut_temp_T_2[15] | _adderOut_temp_T_2[14] | _GEN_1)
    & lzd_adderOut == 4'hD;
  reg         io_res_is_nan_r;
  reg         io_res_is_posInf_r;
  reg         io_res_is_negInf_r;
  always @(posedge clock) begin
    if (reset)
      io_valid_out_REG <= 1'h0;
    else
      io_valid_out_REG <= io_valid_in;
    if (io_valid_in) begin
      automatic logic [13:0] shiftRight_out =
        {_shiftRight_out_shiftRight_res_shiftRightJam_io_out[13:1],
         _shiftRight_out_shiftRight_res_shiftRightJam_io_out[0]
           | _shiftRight_out_shiftRight_res_shiftRightJam_io_sticky};
      automatic logic        res_is_nan_S0 =
        io_a_is_nan | io_b_is_nan | io_a_is_posInf & io_b_is_negInf | io_a_is_negInf
        & io_b_is_posInf;
      is_fp16_S1 <= io_is_fp16;
      a_in_S1_exp <= io_a_exp;
      a_in_S1_sig <= io_a_sig;
      b_in_S1_exp <= io_b_exp;
      b_in_S1_sig <= io_b_sig;
      sign_a_S1 <= io_a_sign;
      sign_b_S1 <= io_b_sign;
      exp_a_S1 <= io_a_exp;
      exp_b_S1 <= io_b_exp;
      abs_a_gt_b_S1 <=
        exp_diff_b_minus_a[8] | exp_diff_a_minus_b == 9'h0
        & io_a_sig[13:3] > io_b_sig[13:3];
      adderIn_a_S1_r <= exp_diff_a_minus_b[8] ? shiftRight_out : io_a_sig;
      adderIn_b_S1_r <= exp_diff_a_minus_b[8] ? io_b_sig : shiftRight_out;
      exp_a_gte_b_S1 <= ~(exp_diff_a_minus_b[8]);
      io_res_is_nan_r <= res_is_nan_S0;
      io_res_is_posInf_r <= ~res_is_nan_S0 & (io_a_is_posInf | io_b_is_posInf);
      io_res_is_negInf_r <= ~res_is_nan_S0 & (io_a_is_negInf | io_b_is_negInf);
    end
  end // always @(posedge)
  ShiftRightJam shiftRight_out_shiftRight_res_shiftRightJam (
    .io_in     (exp_diff_a_minus_b[8] ? io_a_sig : io_b_sig),
    .io_shamt
      (exp_diff_a_minus_b[8]
         ? (a_dominates ? 4'h0 : b_dominates ? 4'hF : exp_diff_b_minus_a[3:0])
         : a_dominates ? 4'hF : b_dominates ? 4'h0 : exp_diff_a_minus_b[3:0]),
    .io_out    (_shiftRight_out_shiftRight_res_shiftRightJam_io_out),
    .io_sticky (_shiftRight_out_shiftRight_res_shiftRightJam_io_sticky)
  );
  assign io_res_sign = ~_GEN_2 & sign_adderOut;
  assign io_res_exp =
    _GEN_2
      ? 8'h0
      : exp_adderOut
        - (_adderOut_temp_T_2[15]
             ? 8'hFF
             : _adderOut_temp_T_2[14]
                 ? 8'h0
                 : _GEN_1 ? _exp_adderOut_over_1_T : {4'h0, lzd_adderOut + 4'h1});
  assign io_res_sig = _GEN_2 ? 15'h0 : _sig_adderOut_shifted_T[14:0];
  assign io_res_is_posInf = io_res_is_posInf_r | adderOut_is_inf & ~sign_adderOut;
  assign io_res_is_negInf = io_res_is_negInf_r | adderOut_is_inf & sign_adderOut;
  assign io_res_is_nan = io_res_is_nan_r;
  assign io_valid_out = io_valid_out_REG;
endmodule

module ShiftRightJam_1(
  input  [26:0] io_in,
  input  [4:0]  io_shamt,
  output [26:0] io_out,
  output        io_sticky
);

  wire        exceed_max_shift = io_shamt > 5'h1B;
  wire [31:0] _sticky_mask_T = 32'h1 << io_shamt;
  assign io_out = exceed_max_shift ? 27'h0 : io_in >> io_shamt;
  assign io_sticky = |(io_in & (_sticky_mask_T[26:0] - 27'h1 | {27{exceed_max_shift}}));
endmodule

