         _shiftRight_out_shiftRight_res_shiftRightJam_io_out[0]
           | _shiftRight_out_shiftRight_res_shiftRightJam_io_sticky};
      automatic logic        res_is_nan_S0 =
        io_a_is_nan | io_b_is_nan | io_a_is_posInf & io_b_is_negInf | io_a_is_negInf
        & io_b_is_posInf;
      is_fp16_S1 <= io_is_fp16;
      a_in_S1_exp <= io_a_exp;
      a_in_S1_sig <= io_a_sig;
      b_in_S1_exp <= io_b_exp;
      b_in_S1_sig <= io_b_sig;
      sign_a_S1 <= io_a_sign;
      sign_b_S1 <= io_b_sign;
      exp_a_S1 <= io_a_exp;
      exp_b_S1 <= io_b_exp;
      abs_a_gt_b_S1 <=
        exp_diff_b_minus_a[8] | exp_diff_a_minus_b == 9'h0
        & io_a_sig[26:3] > io_b_sig[26:3];
      adderIn_a_S1_r <= exp_diff_a_minus_b[8] ? shiftRight_out : io_a_sig;
      adderIn_b_S1_r <= exp_diff_a_minus_b[8] ? io_b_sig : shiftRight_out;
      exp_a_gte_b_S1 <= ~(exp_diff_a_minus_b[8]);
      io_res_is_nan_r <= res_is_nan_S0;
      io_res_is_posInf_r <= ~res_is_nan_S0 & (io_a_is_posInf | io_b_is_posInf);
      io_res_is_negInf_r <= ~res_is_nan_S0 & (io_a_is_negInf | io_b_is_negInf);
    end
  end // always @(posedge)
  ShiftRightJam_1 shiftRight_out_shiftRight_res_shiftRightJam (
    .io_in     (exp_diff_a_minus_b[8] ? io_a_sig : io_b_sig),
    .io_shamt
      (exp_diff_a_minus_b[8]
         ? (a_dominates ? 5'h0 : b_dominates ? 5'h1F : exp_diff_b_minus_a[4:0])
         : a_dominates ? 5'h1F : b_dominates ? 5'h0 : exp_diff_a_minus_b[4:0]),
    .io_out    (_shiftRight_out_shiftRight_res_shiftRightJam_io_out),
    .io_sticky (_shiftRight_out_shiftRight_res_shiftRightJam_io_sticky)
  );
  assign io_res_sign = ~_GEN_2 & sign_adderOut;
  assign io_res_exp =
    _GEN_2
      ? 8'h0
      : exp_adderOut
        - (_adderOut_temp_T_2[28]
             ? 8'hFF
             : _adderOut_temp_T_2[27]
                 ? 8'h0
                 : _GEN_1 ? _exp_adderOut_over_1_T : {3'h0, lzd_adderOut + 5'h1});
  assign io_res_sig = _GEN_2 ? 28'h0 : _sig_adderOut_shifted_T[27:0];
  assign io_res_is_posInf = io_res_is_posInf_r | adderOut_is_inf & ~sign_adderOut;
  assign io_res_is_negInf = io_res_is_negInf_r | adderOut_is_inf & sign_adderOut;
  assign io_res_is_nan = io_res_is_nan_r;
endmodule

module FAdd_16_32(
  input         clock,
                reset,
                io_valid_in,
                io_is_bf16,
                io_is_fp16,
                io_is_fp32,
                io_is_widen,
                io_a_already_widen,
  input  [31:0] io_a,
                io_b,
  output [31:0] io_res,
  output        io_valid_out,
                io_valid_S1
);

  wire        _fadd_extSig_fp32_io_res_sign;
  wire [7:0]  _fadd_extSig_fp32_io_res_exp;
  wire [27:0] _fadd_extSig_fp32_io_res_sig;
  wire        _fadd_extSig_fp32_io_res_is_posInf;
  wire        _fadd_extSig_fp32_io_res_is_negInf;
  wire        _fadd_extSig_fp32_io_res_is_nan;
  wire        _fadd_extSig_fp19_io_res_sign;
  wire [7:0]  _fadd_extSig_fp19_io_res_exp;
  wire [14:0] _fadd_extSig_fp19_io_res_sig;
  wire        _fadd_extSig_fp19_io_res_is_posInf;
  wire        _fadd_extSig_fp19_io_res_is_negInf;
  wire        _fadd_extSig_fp19_io_res_is_nan;
  wire        _fadd_extSig_fp19_io_valid_out;
  wire        is_16 = io_is_fp16 | io_is_bf16;
  wire        res_is_fp16 = io_is_fp16 & ~io_is_widen;
  wire [7:0]  exp_high_a = io_is_fp16 ? {3'h0, io_a[30:26]} : io_a[30:23];
  wire [7:0]  exp_low_a = io_is_fp16 ? {3'h0, io_a[14:10]} : io_a[14:7];
  wire [7:0]  exp_high_b = io_is_fp16 ? {3'h0, io_b[30:26]} : io_b[30:23];
  wire [7:0]  exp_low_b = io_is_fp16 ? {3'h0, io_b[14:10]} : io_b[14:7];
  wire [9:0]  frac_high_a_16 = io_is_fp16 ? io_a[25:16] : {io_a[22:16], 3'h0};
  wire [9:0]  frac_low_a_16 = io_is_fp16 ? io_a[9:0] : {io_a[6:0], 3'h0};
  wire [9:0]  frac_high_b_16 = io_is_fp16 ? io_b[25:16] : {io_b[22:16], 3'h0};
  wire [9:0]  frac_low_b_16 = io_is_fp16 ? io_b[9:0] : {io_b[6:0], 3'h0};
  wire [7:0]  _exp_is_all1s_3_T = io_is_fp16 ? 8'h1F : 8'hFF;
  wire        exp_is_all1s_0 = exp_low_a == _exp_is_all1s_3_T;
  wire        exp_is_all1s_1 = exp_low_b == _exp_is_all1s_3_T;
  wire        exp_is_all1s_2 = exp_high_a == _exp_is_all1s_3_T;
  wire        exp_is_all1s_3 = exp_high_b == _exp_is_all1s_3_T;
  wire        is_inf_16_0 = exp_is_all1s_0 & ~(|frac_low_a_16);
  wire        is_inf_16_1 = exp_is_all1s_1 & ~(|frac_low_b_16);
  wire        is_subnorm_0 = is_16 & exp_low_a == 8'h0;
  wire        is_subnorm_1 = is_16 & exp_low_b == 8'h0;
  wire        is_fp16_widen = io_is_fp16 & io_is_widen;
  wire        _fadd_extSig_fp32_io_a_is_negInf_T =
    is_16 ? exp_is_all1s_2 & ~(|frac_high_a_16) : exp_is_all1s_2 & ~(|(io_a[22:0]));
  wire        _fadd_extSig_fp32_io_b_is_negInf_T =
    is_16 ? exp_is_all1s_3 & ~(|frac_high_b_16) : exp_is_all1s_3 & ~(|(io_b[22:0]));
  reg         res_is_32_S1;
  reg         res_is_fp16_S1;
  reg         valid_S2;
  reg         res_extSig_fp19_S2_sign;
  reg  [7:0]  res_extSig_fp19_S2_exp;
  reg  [14:0] res_extSig_fp19_S2_sig;
  reg         res_extSig_fp32_S2_sign;
  reg  [7:0]  res_extSig_fp32_S2_exp;
  reg  [27:0] res_extSig_fp32_S2_sig;
  reg         res_is_32_S2;
  reg         res_is_fp16_S2;
  reg         res_is_posInf_high_S2;
  reg         res_is_negInf_high_S2;
  reg         res_is_nan_high_S2;
  reg         res_is_posInf_low_S2;
  reg         res_is_negInf_low_S2;
  reg         res_is_nan_low_S2;
  wire [11:0] sig_res_low_tmp =
    {1'h0, res_extSig_fp19_S2_sig[14:4]}
    + {8'h0,
       res_is_fp16_S2
         ? {3'h0,
            res_extSig_fp19_S2_sig[3]
              & ((|(res_extSig_fp19_S2_sig[2:0])) | res_extSig_fp19_S2_sig[4])}
         : {res_extSig_fp19_S2_sig[6]
              & ((|(res_extSig_fp19_S2_sig[5:0])) | res_extSig_fp19_S2_sig[7]),
            3'h0}};
  wire [10:0] sig_res_low =
    sig_res_low_tmp[11] ? sig_res_low_tmp[11:1] : sig_res_low_tmp[10:0];
  wire [7:0]  _exp_adjust_res_low_T_1 =
    res_extSig_fp19_S2_exp + {7'h0, sig_res_low_tmp[11]};
  wire        isInf_res_low =
    sig_res_low_tmp[11]
    & (res_is_fp16_S2
         ? res_extSig_fp19_S2_exp == 8'h1E
         : res_extSig_fp19_S2_exp == 8'hFE);
  wire [7:0]  exp_res_low =
    _exp_adjust_res_low_T_1 == 8'h1 & ~(sig_res_low[10]) ? 8'h0 : _exp_adjust_res_low_T_1;
  wire [24:0] sig_res_high_tmp =
    {1'h0, res_extSig_fp32_S2_sig[27:4]}
    + {8'h0,
       res_is_32_S2
         ? {16'h0,
            res_extSig_fp32_S2_sig[3]
              & ((|(res_extSig_fp32_S2_sig[2:0])) | res_extSig_fp32_S2_sig[4])}
         : res_is_fp16_S2
             ? {3'h0,
                res_extSig_fp32_S2_sig[16]
                  & ((|(res_extSig_fp32_S2_sig[15:0])) | res_extSig_fp32_S2_sig[17]),
                13'h0}
             : {res_extSig_fp32_S2_sig[19]
                  & ((|(res_extSig_fp32_S2_sig[18:0])) | res_extSig_fp32_S2_sig[20]),
                16'h0}};
  wire [23:0] sig_res_high =
    sig_res_high_tmp[24] ? sig_res_high_tmp[24:1] : sig_res_high_tmp[23:0];
  wire [7:0]  _exp_adjust_res_high_T_1 =
    res_extSig_fp32_S2_exp + {7'h0, sig_res_high_tmp[24]};
  wire        isInf_res_high =
    sig_res_high_tmp[24]
    & (res_is_fp16_S2
         ? res_extSig_fp32_S2_exp == 8'h1E
         : res_extSig_fp32_S2_exp == 8'hFE);
  wire [7:0]  exp_res_high =
    _exp_adjust_res_high_T_1 == 8'h1 & ~(sig_res_high[23])
      ? 8'h0
      : _exp_adjust_res_high_T_1;
  always @(posedge clock) begin
    if (io_valid_in) begin
      res_is_32_S1 <= io_is_widen | io_is_fp32;
      res_is_fp16_S1 <= res_is_fp16;
    end
    if (_fadd_extSig_fp19_io_valid_out) begin
      res_extSig_fp19_S2_sign <= _fadd_extSig_fp19_io_res_sign;
      res_extSig_fp19_S2_exp <= _fadd_extSig_fp19_io_res_exp;
      res_extSig_fp19_S2_sig <= _fadd_extSig_fp19_io_res_sig;
      res_extSig_fp32_S2_sign <= _fadd_extSig_fp32_io_res_sign;
      res_extSig_fp32_S2_exp <= _fadd_extSig_fp32_io_res_exp;
      res_extSig_fp32_S2_sig <= _fadd_extSig_fp32_io_res_sig;
      res_is_32_S2 <= res_is_32_S1;
      res_is_fp16_S2 <= res_is_fp16_S1;
      res_is_posInf_high_S2 <= _fadd_extSig_fp32_io_res_is_posInf;
      res_is_negInf_high_S2 <= _fadd_extSig_fp32_io_res_is_negInf;
      res_is_nan_high_S2 <= _fadd_extSig_fp32_io_res_is_nan;
      res_is_posInf_low_S2 <= _fadd_extSig_fp19_io_res_is_posInf;
      res_is_negInf_low_S2 <= _fadd_extSig_fp19_io_res_is_negInf;
      res_is_nan_low_S2 <= _fadd_extSig_fp19_io_res_is_nan;
    end
    if (reset)
      valid_S2 <= 1'h0;
    else
      valid_S2 <= _fadd_extSig_fp19_io_valid_out;
  end // always @(posedge)
  FAdd_extSig fadd_extSig_fp19 (
    .clock            (clock),
    .reset            (reset),
    .io_valid_in      (io_valid_in),
    .io_is_fp16       (io_is_fp16),
    .io_a_sign        (io_a[15]),
    .io_a_exp         (is_subnorm_0 ? 8'h1 : exp_low_a),
    .io_a_sig         ({~is_subnorm_0, frac_low_a_16, 3'h0}),
    .io_b_sign        (io_b[15]),
    .io_b_exp         (is_subnorm_1 ? 8'h1 : exp_low_b),
    .io_b_sig         ({~is_subnorm_1, frac_low_b_16, 3'h0}),
    .io_a_is_posInf   (is_inf_16_0 & ~(io_a[15])),
    .io_b_is_posInf   (is_inf_16_1 & ~(io_b[15])),
    .io_a_is_negInf   (is_inf_16_0 & io_a[15]),
    .io_b_is_negInf   (is_inf_16_1 & io_b[15]),
    .io_a_is_nan      (exp_is_all1s_0 & (|frac_low_a_16)),
    .io_b_is_nan      (exp_is_all1s_1 & (|frac_low_b_16)),
    .io_res_sign      (_fadd_extSig_fp19_io_res_sign),
    .io_res_exp       (_fadd_extSig_fp19_io_res_exp),
    .io_res_sig       (_fadd_extSig_fp19_io_res_sig),
    .io_res_is_posInf (_fadd_extSig_fp19_io_res_is_posInf),
    .io_res_is_negInf (_fadd_extSig_fp19_io_res_is_negInf),
    .io_res_is_nan    (_fadd_extSig_fp19_io_res_is_nan),
    .io_valid_out     (_fadd_extSig_fp19_io_valid_out)
  );
  FAdd_extSig_1 fadd_extSig_fp32 (
    .clock            (clock),
    .io_valid_in      (io_valid_in),
    .io_is_fp16       (res_is_fp16),
    .io_a_sign        (io_a[31]),
    .io_a_exp
      (((|exp_high_a) ? exp_high_a : 8'h1)
       + {1'h0, is_fp16_widen & ~io_a_already_widen ? 7'h70 : 7'h0}),
    .io_a_sig
      ({|exp_high_a,
        is_16 & ~io_a_already_widen ? {frac_high_a_16, 13'h0} : io_a[22:0],
        3'h0}),
    .io_b_sign        (io_b[31]),
    .io_b_exp
      (((|exp_high_b) ? exp_high_b : 8'h1) + {1'h0, is_fp16_widen ? 7'h70 : 7'h0}),
    .io_b_sig         ({|exp_high_b, is_16 ? {frac_high_b_16, 13'h0} : io_b[22:0], 3'h0}),
    .io_a_is_posInf   (_fadd_extSig_fp32_io_a_is_negInf_T & ~(io_a[31])),
    .io_b_is_posInf   (_fadd_extSig_fp32_io_b_is_negInf_T & ~(io_b[31])),
    .io_a_is_negInf   (_fadd_extSig_fp32_io_a_is_negInf_T & io_a[31]),
    .io_b_is_negInf   (_fadd_extSig_fp32_io_b_is_negInf_T & io_b[31]),
    .io_a_is_nan
      (is_16 ? exp_is_all1s_2 & (|frac_high_a_16) : exp_is_all1s_2 & (|(io_a[22:0]))),
    .io_b_is_nan
      (is_16 ? exp_is_all1s_3 & (|frac_high_b_16) : exp_is_all1s_3 & (|(io_b[22:0]))),
    .io_res_sign      (_fadd_extSig_fp32_io_res_sign),
    .io_res_exp       (_fadd_extSig_fp32_io_res_exp),
    .io_res_sig       (_fadd_extSig_fp32_io_res_sig),
    .io_res_is_posInf (_fadd_extSig_fp32_io_res_is_posInf),
    .io_res_is_negInf (_fadd_extSig_fp32_io_res_is_negInf),
    .io_res_is_nan    (_fadd_extSig_fp32_io_res_is_nan)
  );
  assign io_res =
    res_is_32_S2
      ? (res_is_nan_high_S2
           ? 32'h7FC00000
           : res_is_posInf_high_S2
               ? 32'h7F800000
               : res_is_negInf_high_S2
                   ? 32'hFF800000
                   : {res_extSig_fp32_S2_sign,
                      isInf_res_high ? 31'h7F800000 : {exp_res_high, sig_res_high[22:0]}})
      : res_is_fp16_S2
          ? {res_is_nan_high_S2
               ? 16'h7E00
               : res_is_posInf_high_S2
                   ? 16'h7C00
                   : res_is_negInf_high_S2
                       ? 16'hFC00
                       : {res_extSig_fp32_S2_sign,
                          isInf_res_high
                            ? 15'h7C00
                            : {exp_res_high[4:0], sig_res_high[22:13]}},
             res_is_nan_low_S2
               ? 16'h7E00
               : res_is_posInf_low_S2
                   ? 16'h7C00
                   : res_is_negInf_low_S2
                       ? 16'hFC00
                       : {res_extSig_fp19_S2_sign,
                          isInf_res_low
                            ? 15'h7C00
                            : {exp_res_low[4:0], sig_res_low[9:0]}}}
          : {res_is_nan_high_S2
               ? 16'h7FC0
               : res_is_posInf_high_S2
                   ? 16'h7F80
                   : res_is_negInf_high_S2
                       ? 16'hFF80
                       : {res_extSig_fp32_S2_sign,
                          isInf_res_high
                            ? 15'h7F80
                            : {exp_res_high, sig_res_high[22:16]}},
             res_is_nan_low_S2
               ? 16'h7FC0
               : res_is_posInf_low_S2
                   ? 16'h7F80
                   : res_is_negInf_low_S2
                       ? 16'hFF80
                       : {res_extSig_fp19_S2_sign,
                          isInf_res_low ? 15'h7F80 : {exp_res_low, sig_res_low[9:3]}}};
  assign io_valid_out = valid_S2;
  assign io_valid_S1 = _fadd_extSig_fp19_io_valid_out;
endmodule

module LaneFAdd(
