    io_in_bits_uop_ctrl_widen | io_in_bits_uop_ctrl_widen2;
  wire [31:0]  vs2_32b_0 =
    io_in_bits_uop_ctrl_widen2
      ? io_in_bits_vs2[31:0]
      : {io_in_bits_uop_ctrl_widen
           ? (io_in_bits_uop_uopIdx[0] ? io_in_bits_vs2[47:32] : io_in_bits_vs2[15:0])
