         io_in_bits_vs2[15:0]};
  wire [31:0]  _vs1_32b_0_T_5 =
    io_in_bits_uop_ctrl_funct3[2]
      ? rs1[31:0]
      : {io_in_bits_uop_ctrl_widen
           ? (io_in_bits_uop_uopIdx[0] ? io_in_bits_vs1[47:32] : io_in_bits_vs1[15:0])
           : io_in_bits_vs1[31:16],
         io_in_bits_vs1[15:0]};
  wire [31:0]  vs2_32b_1 =
    io_in_bits_uop_ctrl_widen2
      ? io_in_bits_vs2[63:32]
      : {io_in_bits_uop_ctrl_widen
           ? (io_in_bits_uop_uopIdx[0] ? io_in_bits_vs2[63:48] : io_in_bits_vs2[31:16])
           : io_in_bits_vs2[63:48],
         io_in_bits_vs2[47:32]};
  wire [31:0]  _vs1_32b_1_T_5 =
    io_in_bits_uop_ctrl_funct3[2]
      ? rs1[31:0]
      : {io_in_bits_uop_ctrl_widen
           ? (io_in_bits_uop_uopIdx[0] ? io_in_bits_vs1[63:48] : io_in_bits_vs1[31:16])
