module Estimate7(
  input         clock,
                reset,
                io_fire,
  input  [63:0] io_src,
  input  [7:0]  io_opType,
  input  [2:0]  io_rm,
  input  [3:0]  io_input1H,
                io_output1H,
  output [63:0] io_result
);

  wire [6:0]   _rec7Table_out;
  wire [6:0]   _rsqrt7Table_out;
  wire [6:0]   _leadZerosNext_clz_io_out;
  reg          fireReg_last_r;
  wire [63:0]  input_0 =
    (io_input1H[1] ? {io_src[15], 6'h0, io_src[14:0], 42'h0} : 64'h0)
    | (io_input1H[2] ? {io_src[31], 3'h0, io_src[30:0], 29'h0} : 64'h0)
    | (io_input1H[3] ? io_src : 64'h0);
  reg  [2:0]   rm;
  reg          expIsOnesSrc;
  reg          isSubnormalSrc;
  reg          isRec;
  reg          signSrc;
  reg          isZeroSrc;
  reg          isSubnormalRec2;
  reg          isInfSrc;
  reg          isNaNSrc;
  reg          isNormalRec0;
  reg          isNormalRec1;
  reg          isNormalRec2;
  reg          isSubnormalRec0;
  reg          isSubnormalRec1;
  reg  [3:0]   output1HReg;
  reg  [63:0]  result;
  wire [63:0]  clzIn = {input_0[51:0], 12'h0};
  reg  [12:0]  expAdderIn0;
  reg  [12:0]  expAdderIn1;
  reg          expNormaled0;
  reg  [63:0]  fracSrcLeft;
  reg  [6:0]   leadZeros;
  wire [191:0] _shiftLeft_T_1 = {127'h0, fracSrcLeft, 1'h0} << leadZeros;
  wire [6:0]   fracNormaled = isSubnormalSrc ? _shiftLeft_T_1[63:57] : fracSrcLeft[63:57];
  always @(posedge clock) begin
    automatic logic       isRecNext;
    automatic logic [2:0] decodeFloatSrc;
    automatic logic       isSubnormalSrcNext;
    isRecNext = io_opType[5] & io_opType[0];
    decodeFloatSrc =
      (io_input1H[1] ? {|(input_0[51:42]), &(input_0[56:52]), |(input_0[56:52])} : 3'h0)
      | (io_input1H[2] ? {|(input_0[51:29]), &(input_0[59:52]), |(input_0[59:52])} : 3'h0)
      | (io_input1H[3] ? {|(input_0[51:0]), &(input_0[62:52]), |(input_0[62:52])} : 3'h0);
    isSubnormalSrcNext = ~(decodeFloatSrc[0]) & decodeFloatSrc[2];
    if (reset) begin
      fireReg_last_r <= 1'h0;
      rm <= 3'h0;
      expIsOnesSrc <= 1'h0;
      isSubnormalSrc <= 1'h0;
      isRec <= 1'h0;
      signSrc <= 1'h0;
      isZeroSrc <= 1'h0;
      isSubnormalRec2 <= 1'h0;
      isInfSrc <= 1'h0;
      isNaNSrc <= 1'h0;
      isNormalRec0 <= 1'h0;
      isNormalRec1 <= 1'h0;
      isNormalRec2 <= 1'h0;
      isSubnormalRec0 <= 1'h0;
      isSubnormalRec1 <= 1'h0;
      output1HReg <= 4'h0;
      result <= 64'h0;
      expNormaled0 <= 1'h0;
      fracSrcLeft <= 64'h0;
    end
    else begin
      if (io_fire | fireReg_last_r)
        fireReg_last_r <= io_fire;
      if (io_fire) begin
        automatic logic [1:0] decodeFloatSrcRec =
          (io_input1H[1]
             ? {(&(input_0[56:54])) & ~(input_0[53]) & input_0[52],
                (&(input_0[56:53])) & ~(input_0[52])}
             : 2'h0)
          | (io_input1H[2]
               ? {(&(input_0[59:54])) & ~(input_0[53]) & input_0[52],
                  (&(input_0[59:53])) & ~(input_0[52])}
               : 2'h0)
          | (io_input1H[3]
               ? {(&(input_0[62:54])) & ~(input_0[53]) & input_0[52],
                  (&(input_0[62:53])) & ~(input_0[52])}
               : 2'h0);
        rm <= io_rm;
        expIsOnesSrc <= decodeFloatSrc[1];
        isSubnormalSrc <= isSubnormalSrcNext;
        isRec <= isRecNext;
        signSrc <= input_0[63];
        isZeroSrc <= ~(decodeFloatSrc[0]) & ~(decodeFloatSrc[2]);
        isSubnormalRec2 <= isSubnormalSrcNext & input_0[51:50] == 2'h0;
        isInfSrc <= decodeFloatSrc[1] & ~(decodeFloatSrc[2]);
        isNaNSrc <= decodeFloatSrc[1] & decodeFloatSrc[2];
        isNormalRec0 <= decodeFloatSrcRec[0];
        isNormalRec1 <= decodeFloatSrcRec[1];
        isNormalRec2 <=
          decodeFloatSrc[0] & ~(decodeFloatSrc[1]) & ~(decodeFloatSrcRec[0])
          & ~(decodeFloatSrcRec[1]);
        isSubnormalRec0 <= isSubnormalSrcNext & input_0[51];
        isSubnormalRec1 <= isSubnormalSrcNext & ~(input_0[51]) & input_0[50];
        output1HReg <= io_output1H;
        expNormaled0 <= isSubnormalSrcNext ? _leadZerosNext_clz_io_out[0] : input_0[52];
        fracSrcLeft <= clzIn;
      end
      if (fireReg_last_r) begin
        automatic logic        rmin =
          rm == 3'h1 | signSrc & rm == 3'h3 | ~signSrc & rm == 3'h2;
        automatic logic [11:0] _exp_T = expAdderIn0[11:0] + expAdderIn1[11:0];
        automatic logic [6:0]  fracEstimate = isRec ? _rec7Table_out : _rsqrt7Table_out;
        automatic logic        _recResultMap_T_88 = isZeroSrc | isSubnormalRec2 & ~rmin;
        automatic logic        _recResultMap_T_85 =
          isNormalRec2 | isSubnormalRec0 | isSubnormalRec1;
        automatic logic        _recResultMap_T_84 = isSubnormalRec2 & rmin;
        automatic logic        _sqrtResultMap_T_45 = signSrc & ~isZeroSrc | isNaNSrc;
        automatic logic        _sqrtResultMap_T_43 =
          ~signSrc & ~isZeroSrc & ~expIsOnesSrc;
        result <=
          isRec
            ? {32'h0,
               {16'h0,
                output1HReg[1]
                  ? (isNaNSrc ? 16'h7E00 : 16'h0) | (isInfSrc ? {signSrc, 15'h0} : 16'h0)
                    | (_recResultMap_T_88 ? {signSrc, 15'h7C00} : 16'h0)
                    | (isNormalRec0 ? {signSrc, 7'h1, fracEstimate, 1'h0} : 16'h0)
                    | (isNormalRec1 ? {signSrc, 6'h1, fracEstimate, 2'h0} : 16'h0)
                    | (_recResultMap_T_85
                         ? {signSrc, _exp_T[4:0], fracEstimate, 3'h0}
                         : 16'h0) | (_recResultMap_T_84 ? {signSrc, 15'h7BFF} : 16'h0)
                  : 16'h0}
                 | (output1HReg[2]
                      ? (isNaNSrc ? 32'h7FC00000 : 32'h0)
                        | (isInfSrc ? {signSrc, 31'h0} : 32'h0)
                        | (_recResultMap_T_88 ? {signSrc, 31'h7F800000} : 32'h0)
                        | (isNormalRec0 ? {signSrc, 10'h1, fracEstimate, 14'h0} : 32'h0)
                        | (isNormalRec1 ? {signSrc, 9'h1, fracEstimate, 15'h0} : 32'h0)
                        | (_recResultMap_T_85
                             ? {signSrc, _exp_T[7:0], fracEstimate, 16'h0}
                             : 32'h0)
                        | (_recResultMap_T_84 ? {signSrc, 31'h7F7FFFFF} : 32'h0)
                      : 32'h0)}
              | (output1HReg[3]
                   ? (isNaNSrc ? 64'h7FF8000000000000 : 64'h0)
                     | (isInfSrc ? {signSrc, 63'h0} : 64'h0)
                     | (_recResultMap_T_88 ? {signSrc, 63'h7FF0000000000000} : 64'h0)
                     | (isNormalRec0 ? {signSrc, 13'h1, fracEstimate, 43'h0} : 64'h0)
                     | (isNormalRec1 ? {signSrc, 12'h1, fracEstimate, 44'h0} : 64'h0)
                     | (_recResultMap_T_85
                          ? {signSrc, _exp_T[10:0], fracEstimate, 45'h0}
                          : 64'h0)
                     | (_recResultMap_T_84 ? {signSrc, 63'h7FEFFFFFFFFFFFFF} : 64'h0)
                   : 64'h0)
            : {32'h0,
               {16'h0,
                output1HReg[1]
                  ? (_sqrtResultMap_T_45 ? 16'h7E00 : 16'h0)
                    | (isZeroSrc ? {signSrc, 15'h7C00} : 16'h0)
                    | (_sqrtResultMap_T_43
                         ? {signSrc, _exp_T[5:1], fracEstimate, 3'h0}
                         : 16'h0)
                  : 16'h0}
                 | (output1HReg[2]
                      ? (_sqrtResultMap_T_45 ? 32'h7FC00000 : 32'h0)
                        | (isZeroSrc ? {signSrc, 31'h7F800000} : 32'h0)
                        | (_sqrtResultMap_T_43
                             ? {signSrc, _exp_T[8:1], fracEstimate, 16'h0}
                             : 32'h0)
                      : 32'h0)}
              | (output1HReg[3]
                   ? (_sqrtResultMap_T_45 ? 64'h7FF8000000000000 : 64'h0)
                     | (isZeroSrc ? {signSrc, 63'h7FF0000000000000} : 64'h0)
                     | (_sqrtResultMap_T_43
                          ? {signSrc, _exp_T[11:1], fracEstimate, 45'h0}
                          : 64'h0)
                   : 64'h0);
      end
    end
    if (io_fire) begin
      automatic logic [11:0] _minusExp_T_2 = {1'h1, ~(input_0[62:52])} + 12'h1;
      expAdderIn0 <=
        {1'h0,
         {3'h0,
          {3'h0, io_output1H[1] ? (isRecNext ? 6'h1D : 6'h2C) : 6'h0}
            | (io_output1H[2] ? (isRecNext ? 9'hFD : 9'h17C) : 9'h0)}
           | (io_output1H[3] ? (isRecNext ? 12'h7FD : 12'hBFC) : 12'h0)};
      expAdderIn1 <=
        isSubnormalSrcNext
          ? {6'h0, _leadZerosNext_clz_io_out}
          : {_minusExp_T_2[11], _minusExp_T_2};
      leadZeros <= _leadZerosNext_clz_io_out;
    end
  end // always @(posedge)
  CLZ leadZerosNext_clz (
    .io_in  (clzIn),
    .io_out (_leadZerosNext_clz_io_out)
  );
  Rsqrt7Table rsqrt7Table (
    .src ({expNormaled0, fracNormaled[6:1]}),
    .out (_rsqrt7Table_out)
  );
  Rec7Table rec7Table (
    .src (fracNormaled),
    .out (_rec7Table_out)
  );
  assign io_result = result;
endmodule

module CVT64(
  input         clock,
                reset,
                io_fire,
  input  [63:0] io_src,
  input  [7:0]  io_opType,
  input  [2:0]  io_rm,
  input  [3:0]  io_input1H,
                io_output1H,
  output [63:0] io_result
);

  wire [63:0] _estmate7_io_result;
  wire [63:0] _int2fp_io_result;
  wire [63:0] _fpcvt_io_result;
  wire [2:0]  effectiveRm = io_opType == 8'h87 ? 3'h1 : io_rm;
  reg         fireReg_last_r;
  reg         isFpWiden;
  reg         isFpNarrow;
  reg         isFp2Int;
  reg         isFpCrossHigh;
  reg         isFpCrossLow;
  reg         s1_isInt2Fp;
  reg         s1_isEstimate7;
  reg         s2_isInt2Fp;
  reg         s2_isEstimate7;
  reg         s2_isFPsrc;
  always @(posedge clock) begin
    if (reset) begin
      fireReg_last_r <= 1'h0;
      isFpWiden <= 1'h0;
      isFpNarrow <= 1'h0;
      isFp2Int <= 1'h0;
      isFpCrossHigh <= 1'h0;
      isFpCrossLow <= 1'h0;
      s1_isInt2Fp <= 1'h0;
      s1_isEstimate7 <= 1'h0;
    end
    else begin
      if (io_fire | fireReg_last_r)
        fireReg_last_r <= io_fire;
      if (io_fire) begin
        automatic logic _GEN = io_opType[7] & io_opType[6];
        isFpWiden <= _GEN & ~(io_opType[4]) & io_opType[3];
        isFpNarrow <= _GEN & io_opType[4] & ~(io_opType[3]);
        isFp2Int <= ~(io_opType[6]);
        isFpCrossHigh <= _GEN & io_opType[4] & io_opType[3] & io_output1H[3];
        isFpCrossLow <= _GEN & io_opType[4] & io_opType[3] & io_output1H[1];
        s1_isInt2Fp <= ~(io_opType[7]);
        s1_isEstimate7 <= io_opType[5];
      end
    end
    if (fireReg_last_r) begin
      s2_isInt2Fp <= s1_isInt2Fp;
      s2_isEstimate7 <= s1_isEstimate7;
      s2_isFPsrc <= isFpWiden | isFpNarrow | isFpCrossHigh | isFpCrossLow | isFp2Int;
    end
  end // always @(posedge)
  FP_INCVT fpcvt (
    .clock       (clock),
    .reset       (reset),
    .io_fire     (io_fire),
    .io_src      (io_src),
    .io_opType   (io_opType),
    .io_rm       (effectiveRm),
    .io_input1H  (io_input1H),
    .io_output1H (io_output1H),
    .io_result   (_fpcvt_io_result)
  );
  INT2FP int2fp (
    .clock       (clock),
    .reset       (reset),
    .io_fire     (io_fire),
    .io_src      (io_src),
    .io_opType   (io_opType),
    .io_rm       (effectiveRm),
    .io_input1H  (io_input1H),
    .io_output1H (io_output1H),
    .io_result   (_int2fp_io_result)
  );
  Estimate7 estmate7 (
    .clock       (clock),
    .reset       (reset),
    .io_fire     (io_fire),
    .io_src      (io_src),
    .io_opType   (io_opType),
    .io_rm       (effectiveRm),
    .io_input1H  (io_input1H),
    .io_output1H (io_output1H),
    .io_result   (_estmate7_io_result)
  );
  assign io_result =
    (s2_isInt2Fp ? _int2fp_io_result : 64'h0) | (s2_isFPsrc ? _fpcvt_io_result : 64'h0)
    | (s2_isEstimate7 ? _estmate7_io_result : 64'h0);
endmodule

module VCVT(
  input         clock,
                reset,
