  input  [63:0] io_src,
  input  [7:0]  io_opType,
  input  [2:0]  io_rm,
  input  [3:0]  io_input1H,
                io_output1H,
  output [63:0] io_result
);

  CVT64 vcvtImpl (
    .clock       (clock),
    .reset       (reset),
    .io_fire     (io_fire),
    .io_src      (io_src),
    .io_opType   (io_opType),
    .io_rm       (io_rm),
    .io_input1H  (io_input1H),
    .io_output1H (io_output1H),
    .io_result   (io_result)
  );
endmodule

module ShiftRightJam_5(
  input  [24:0] io_in,
  input  [7:0]  io_shamt,
  output [24:0] io_out,
  output        io_sticky
);

  wire        exceed_max_shift = io_shamt > 8'h19;
  wire [31:0] _sticky_mask_T = 32'h1 << io_shamt[4:0];
  assign io_out = exceed_max_shift ? 25'h0 : io_in >> io_shamt;
  assign io_sticky = |(io_in & (_sticky_mask_T[24:0] - 25'h1 | {25{exceed_max_shift}}));
endmodule

module CLZ_3(
  input  [31:0] io_in,
  output [5:0]  io_out
);

  assign io_out =
    io_in[31]
      ? 6'h0
      : io_in[30]
          ? 6'h1
          : io_in[29]
              ? 6'h2
              : io_in[28]
                  ? 6'h3
                  : io_in[27]
                      ? 6'h4
                      : io_in[26]
                          ? 6'h5
                          : io_in[25]
                              ? 6'h6
                              : io_in[24]
                                  ? 6'h7
                                  : io_in[23]
                                      ? 6'h8
                                      : io_in[22]
                                          ? 6'h9
                                          : io_in[21]
                                              ? 6'hA
                                              : io_in[20]
                                                  ? 6'hB
                                                  : io_in[19]
                                                      ? 6'hC
                                                      : io_in[18]
                                                          ? 6'hD
                                                          : io_in[17]
                                                              ? 6'hE
                                                              : io_in[16]
                                                                  ? 6'hF
                                                                  : io_in[15]
                                                                      ? 6'h10
                                                                      : io_in[14]
                                                                          ? 6'h11
                                                                          : io_in[13]
                                                                              ? 6'h12
                                                                              : io_in[12]
                                                                                  ? 6'h13
