  output [9:0]   io_out_uop_bits_csr_vl,
  output [2:0]   io_out_uop_bits_csr_vsew,
                 io_out_uop_bits_veewVd,
                 io_out_uop_bits_uopIdx,
  output         io_out_uop_bits_uopEnd,
  output [4:0]   io_out_uop_bits_ldestUop,
  output         io_out_uop_bits_ldestValUop,
                 io_out_uop_bits_predEnable,
  output [511:0] io_out_uop_bits_predMask
);

  wire [63:0]  _vcvt_io_result;
  reg          reg_valid_0;
  reg          reg_valid_1;
  reg  [5:0]   reg_uop_0_ctrl_funct6;
  reg  [2:0]   reg_uop_0_ctrl_funct3;
  reg          reg_uop_0_ctrl_load;
  reg          reg_uop_0_ctrl_div;
  reg          reg_uop_0_ctrl_redu;
  reg          reg_uop_0_ctrl_narrow;
  reg          reg_uop_0_ctrl_narrow_to_1;
