  reg  [2:0]   reg_uop_0_csr_vsew;
  reg  [2:0]   reg_uop_0_veewVd;
  reg  [2:0]   reg_uop_0_uopIdx;
  reg          reg_uop_0_uopEnd;
  reg  [4:0]   reg_uop_0_ldestUop;
  reg          reg_uop_0_ldestValUop;
  reg          reg_uop_0_predEnable;
  reg  [511:0] reg_uop_0_predMask;
  reg  [5:0]   reg_uop_1_ctrl_funct6;
  reg  [2:0]   reg_uop_1_ctrl_funct3;
  reg          reg_uop_1_ctrl_load;
  reg          reg_uop_1_ctrl_div;
  reg          reg_uop_1_ctrl_redu;
  reg          reg_uop_1_ctrl_narrow;
  reg          reg_uop_1_ctrl_narrow_to_1;
  reg  [9:0]   reg_uop_1_csr_vl;
  reg  [2:0]   reg_uop_1_csr_vsew;
  reg  [2:0]   reg_uop_1_veewVd;
  reg  [2:0]   reg_uop_1_uopIdx;
  reg          reg_uop_1_uopEnd;
  reg  [4:0]   reg_uop_1_ldestUop;
  reg          reg_uop_1_ldestValUop;
  reg          reg_uop_1_predEnable;
  reg  [511:0] reg_uop_1_predMask;
  reg  [1:0]   reg_widen_0;
  reg  [1:0]   reg_widen_1;
  wire         widen_or_single =
    reg_valid_1 & (reg_widen_1 == 2'h1 | reg_widen_1 == 2'h0);
  reg  [31:0]  narrow_result_half;
  wire         _GEN = reg_uop_1_ctrl_narrow & (reg_uop_1_uopEnd | reg_uop_1_uopIdx[0]);
  always @(posedge clock) begin
    reg_valid_0 <= io_fire;
    reg_valid_1 <= reg_valid_0;
    if (io_fire) begin
      reg_uop_0_ctrl_funct6 <= io_in_uop_ctrl_funct6;
      reg_uop_0_ctrl_funct3 <= io_in_uop_ctrl_funct3;
      reg_uop_0_ctrl_load <= io_in_uop_ctrl_load;
      reg_uop_0_ctrl_div <= io_in_uop_ctrl_div;
      reg_uop_0_ctrl_redu <= io_in_uop_ctrl_redu;
      reg_uop_0_ctrl_narrow <= io_in_uop_ctrl_narrow;
      reg_uop_0_ctrl_narrow_to_1 <= io_in_uop_ctrl_narrow_to_1;
      reg_uop_0_csr_vl <= io_in_uop_csr_vl;
      reg_uop_0_csr_vsew <= io_in_uop_csr_vsew;
      reg_uop_0_veewVd <= io_in_uop_veewVd;
      reg_uop_0_uopIdx <= io_in_uop_uopIdx;
      reg_uop_0_uopEnd <= io_in_uop_uopEnd;
      reg_uop_0_ldestUop <= io_in_uop_ldestUop;
      reg_uop_0_ldestValUop <= io_in_uop_ldestValUop;
      reg_uop_0_predEnable <= io_in_uop_predEnable;
      reg_uop_0_predMask <= io_in_uop_predMask;
      reg_widen_0 <= io_op_code[4:3];
    end
    if (reg_valid_0) begin
      reg_uop_1_ctrl_funct6 <= reg_uop_0_ctrl_funct6;
      reg_uop_1_ctrl_funct3 <= reg_uop_0_ctrl_funct3;
      reg_uop_1_ctrl_load <= reg_uop_0_ctrl_load;
      reg_uop_1_ctrl_div <= reg_uop_0_ctrl_div;
      reg_uop_1_ctrl_redu <= reg_uop_0_ctrl_redu;
      reg_uop_1_ctrl_narrow <= reg_uop_0_ctrl_narrow;
      reg_uop_1_ctrl_narrow_to_1 <= reg_uop_0_ctrl_narrow_to_1;
      reg_uop_1_csr_vl <= reg_uop_0_csr_vl;
      reg_uop_1_csr_vsew <= reg_uop_0_csr_vsew;
      reg_uop_1_veewVd <= reg_uop_0_veewVd;
      reg_uop_1_uopIdx <= reg_uop_0_uopIdx;
      reg_uop_1_uopEnd <= reg_uop_0_uopEnd;
      reg_uop_1_ldestUop <= reg_uop_0_ldestUop;
      reg_uop_1_ldestValUop <= reg_uop_0_ldestValUop;
      reg_uop_1_predEnable <= reg_uop_0_predEnable;
      reg_uop_1_predMask <= reg_uop_0_predMask;
      reg_widen_1 <= reg_widen_0;
    end
    if (reg_valid_1 & ~(reg_uop_1_uopIdx[0]))
      narrow_result_half <= _vcvt_io_result[31:0];
  end // always @(posedge)
  VectorCvt vcvt (
    .clock     (clock),
    .reset     (reset),
    .io_fire   (io_fire),
    .io_src
      (io_uop_idx & io_op_code[4:3] == 2'h1 ? {io_vs2[31:0], io_vs2[63:32]} : io_vs2),
    .io_opType (io_op_code),
    .io_sew    (io_sew),
    .io_rm     (io_rm),
    .io_result (_vcvt_io_result)
  );
  assign io_result =
    widen_or_single
      ? _vcvt_io_result
      : _GEN & reg_valid_1
          ? (reg_uop_1_uopIdx == 3'h0 & reg_uop_1_uopEnd
               ? {32'h0, _vcvt_io_result[31:0]}
               : {_vcvt_io_result[31:0], narrow_result_half})
          : 64'h0;
  assign io_out_uop_valid = (widen_or_single | _GEN) & reg_valid_1;
  assign io_out_uop_bits_ctrl_funct6 = reg_uop_1_ctrl_funct6;
  assign io_out_uop_bits_ctrl_funct3 = reg_uop_1_ctrl_funct3;
  assign io_out_uop_bits_ctrl_load = reg_uop_1_ctrl_load;
  assign io_out_uop_bits_ctrl_div = reg_uop_1_ctrl_div;
  assign io_out_uop_bits_ctrl_redu = reg_uop_1_ctrl_redu;
  assign io_out_uop_bits_ctrl_narrow = reg_uop_1_ctrl_narrow;
  assign io_out_uop_bits_ctrl_narrow_to_1 = reg_uop_1_ctrl_narrow_to_1;
  assign io_out_uop_bits_csr_vl = reg_uop_1_csr_vl;
  assign io_out_uop_bits_csr_vsew = reg_uop_1_csr_vsew;
  assign io_out_uop_bits_veewVd = reg_uop_1_veewVd;
  assign io_out_uop_bits_uopIdx = reg_uop_1_uopIdx;
  assign io_out_uop_bits_uopEnd = reg_uop_1_uopEnd;
  assign io_out_uop_bits_ldestUop = reg_uop_1_ldestUop;
  assign io_out_uop_bits_ldestValUop = reg_uop_1_ldestValUop;
  assign io_out_uop_bits_predEnable = reg_uop_1_predEnable;
  assign io_out_uop_bits_predMask = reg_uop_1_predMask;
endmodule

