    always @(posedge clock) begin
      if (~reset
          & ~(io_in_valid & io_in_bits_uop_ctrl_funct6 == 6'hC
              & io_in_bits_uop_ctrl_funct3[0] & io_in_bits_uop_ctrl_lsrc_0 == 5'h0
