          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  reg  [63:0] vs2_0_0_reg;
  reg         keep_vs2_0_0;
  wire [63:0] vs2_0_0 = keep_vs2_0_0 ? vs2_0_0_reg : io_in_bits_vs2[63:0];
  always @(posedge clock) begin
    if (reset) begin
      vs2_0_0_reg <= 64'h0;
      keep_vs2_0_0 <= 1'h0;
    end
    else begin
      if (keep_vs2_0_0) begin
      end
      else
