module VecProcessor(
  input          clock,
                 reset,
  output         io_req_ready,
  input          io_req_valid,
  input  [63:0]  io_req_bits_hartId,
  input  [3:0]   io_req_bits_instId,
  input  [31:0]  io_req_bits_inst,
  input          io_req_bits_info_isConfig,
                 io_req_bits_info_xrd,
                 io_req_bits_info_frd,
  input  [63:0]  io_req_bits_rs1,
                 io_req_bits_rs2,
  output         io_resp_valid,
  output [63:0]  io_resp_bits_hartId,
  output [3:0]   io_resp_bits_instId,
  output [63:0]  io_resp_bits_data,
  output [4:0]   io_resp_bits_rd,
  output         io_resp_bits_we,
  input          io_spm_readReq_ready,
  output         io_spm_readReq_valid,
  output [63:0]  io_spm_readReq_bits_addr,
  input          io_spm_readResp_valid,
  input  [511:0] io_spm_readResp_bits_data,
  input          io_spm_writeReq_ready,
  output         io_spm_writeReq_valid,
                 io_spm_writeReq_bits_last,
  output [63:0]  io_spm_writeReq_bits_addr,
                 io_spm_writeReq_bits_mask,
  output [511:0] io_spm_writeReq_bits_data
);

  wire        io_req_ready_0;
  wire        _core_io_req_ready;
  wire        _core_io_resp_writeBack_valid;
  wire [63:0] _core_io_resp_writeBack_bits;
  wire [63:0] _csr_io_rd;
  wire [9:0]  _csr_io_csr_vl;
  wire [2:0]  _csr_io_csr_vlmul;
  wire [2:0]  _csr_io_csr_vsew;
  wire        _csr_io_csr_ma;
  wire        _csr_io_csr_ta;
  wire        _coreAccept_T = io_req_ready_0 & io_req_valid;
  wire        coreAccept = _coreAccept_T & ~io_req_bits_info_isConfig;
  reg         pendingWb;
  reg  [63:0] pendingWbData_hartId;
  reg  [3:0]  pendingWbData_instId;
  reg  [63:0] pendingWbData_data;
  reg  [4:0]  pendingWbData_rd;
  reg         pendingWbData_we;
  reg         pendingWbValid;
  wire        needWb =
    ~io_req_bits_info_isConfig & (io_req_bits_info_xrd | io_req_bits_info_frd);
  wire        _GEN = _coreAccept_T & io_req_bits_info_isConfig;
  wire        _GEN_0 = _coreAccept_T & ~io_req_bits_info_isConfig & ~needWb;
  assign io_req_ready_0 = (io_req_bits_info_isConfig | _core_io_req_ready) & ~pendingWb;
  always @(posedge clock) begin
    if (reset) begin
      pendingWb <= 1'h0;
      pendingWbData_hartId <= 64'h0;
      pendingWbData_instId <= 4'h0;
      pendingWbData_data <= 64'h0;
      pendingWbData_rd <= 5'h0;
      pendingWbData_we <= 1'h0;
      pendingWbValid <= 1'h0;
    end
    else begin
      automatic logic _GEN_1;
      automatic logic _GEN_2 = pendingWb & _core_io_resp_writeBack_valid;
      automatic logic _GEN_3 = _GEN | ~pendingWbValid;
      _GEN_1 = _coreAccept_T & needWb;
      pendingWb <= _GEN_3 & (_GEN_1 | pendingWb);
      if (_GEN_1) begin
        pendingWbData_hartId <= io_req_bits_hartId;
        pendingWbData_instId <= io_req_bits_instId;
        pendingWbData_rd <= io_req_bits_inst[11:7];
      end
      if (_GEN_2)
        pendingWbData_data <= _core_io_resp_writeBack_bits;
      else if (_GEN_1)
        pendingWbData_data <= 64'h0;
      pendingWbData_we <= _GEN_1 | pendingWbData_we;
      pendingWbValid <= _GEN_3 & (_GEN_2 | ~_GEN_1 & pendingWbValid);
    end
  end // always @(posedge)
  VCsr csr (
    .clock        (clock),
    .reset        (reset),
    .io_instr     (io_req_bits_inst),
    .io_isConfig  (_coreAccept_T & io_req_bits_info_isConfig),
    .io_rs1       (io_req_bits_rs1),
    .io_rs2       (io_req_bits_rs2),
    .io_rd        (_csr_io_rd),
    .io_csr_vl    (_csr_io_csr_vl),
    .io_csr_vlmul (_csr_io_csr_vlmul),
    .io_csr_vsew  (_csr_io_csr_vsew),
    .io_csr_ma    (_csr_io_csr_ma),
    .io_csr_ta    (_csr_io_csr_ta)
  );
  VecCore core (
    .clock                          (clock),
    .reset                          (reset),
    .io_req_ready                   (_core_io_req_ready),
    .io_req_valid                   (coreAccept),
    .io_req_bits_robIdx_flag        (coreAccept),
    .io_req_bits_robIdx_value       ({4'h0, io_req_bits_instId}),
    .io_req_bits_inst               (io_req_bits_inst),
    .io_req_bits_vcsr_vl            (_csr_io_csr_vl),
    .io_req_bits_vcsr_vlmul         (_csr_io_csr_vlmul),
    .io_req_bits_vcsr_vsew          (_csr_io_csr_vsew),
    .io_req_bits_vcsr_ma            (_csr_io_csr_ma),
    .io_req_bits_vcsr_ta            (_csr_io_csr_ta),
    .io_req_bits_rs1                (io_req_bits_rs1),
    .io_req_bits_rs2                (io_req_bits_rs2),
    .io_resp_writeBack_valid        (_core_io_resp_writeBack_valid),
    .io_resp_writeBack_bits         (_core_io_resp_writeBack_bits),
    .io_resp_spm_readReq_ready      (io_spm_readReq_ready),
    .io_resp_spm_readReq_valid      (io_spm_readReq_valid),
    .io_resp_spm_readReq_bits_addr  (io_spm_readReq_bits_addr),
    .io_resp_spm_readResp_valid     (io_spm_readResp_valid),
    .io_resp_spm_readResp_bits_data (io_spm_readResp_bits_data),
    .io_resp_spm_writeReq_ready     (io_spm_writeReq_ready),
    .io_resp_spm_writeReq_valid     (io_spm_writeReq_valid),
    .io_resp_spm_writeReq_bits_last (io_spm_writeReq_bits_last),
    .io_resp_spm_writeReq_bits_addr (io_spm_writeReq_bits_addr),
    .io_resp_spm_writeReq_bits_mask (io_spm_writeReq_bits_mask),
    .io_resp_spm_writeReq_bits_data (io_spm_writeReq_bits_data)
  );
  assign io_req_ready = io_req_ready_0;
  assign io_resp_valid = _GEN | pendingWbValid | _GEN_0;
  assign io_resp_bits_hartId =
    _GEN
      ? io_req_bits_hartId
      : pendingWbValid ? pendingWbData_hartId : _GEN_0 ? io_req_bits_hartId : 64'h0;
  assign io_resp_bits_instId =
    _GEN
      ? io_req_bits_instId
      : pendingWbValid ? pendingWbData_instId : _GEN_0 ? io_req_bits_instId : 4'h0;
  assign io_resp_bits_data =
    _GEN ? _csr_io_rd : pendingWbValid ? pendingWbData_data : 64'h0;
  assign io_resp_bits_rd =
    _GEN ? io_req_bits_inst[11:7] : pendingWbValid ? pendingWbData_rd : 5'h0;
  assign io_resp_bits_we = _GEN | pendingWbValid & pendingWbData_we;
endmodule

