module CompleteQueue(
  input         clock,
                reset,
                io_resp_valid,
  input  [63:0] io_resp_bits_hartId,
  input  [3:0]  io_resp_bits_instId,
  input  [63:0] io_resp_bits_data,
  input  [4:0]  io_resp_bits_rd,
  input         io_resp_bits_we,
                io_output_ready,
  output        io_output_valid,
  output [63:0] io_output_bits_hartId,
  output [3:0]  io_output_bits_instId,
  output [63:0] io_output_bits_data
);

