  wire        _queue_io_deq_valid;
  wire [63:0] _queue_io_deq_bits_hartId;
  wire [3:0]  _queue_io_deq_bits_instId;
  wire [63:0] _queue_io_deq_bits_data;
  wire [3:0]  _queue_io_count;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset & _queue_io_count == 4'h8 & _queue_io_enq_ready & io_resp_valid
          & ~(io_output_ready & _queue_io_deq_valid)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: The complete queue is overflowing! Why CPU is using so much time to READY?\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  Queue8_VecProcessorResp queue (
    .clock              (clock),
    .reset              (reset),
    .io_enq_ready       (_queue_io_enq_ready),
    .io_enq_valid       (io_resp_valid),
    .io_enq_bits_hartId (io_resp_bits_hartId),
    .io_enq_bits_instId (io_resp_bits_instId),
    .io_enq_bits_data   (io_resp_bits_data),
    .io_enq_bits_rd     (io_resp_bits_rd),
    .io_enq_bits_we     (io_resp_bits_we),
    .io_deq_ready       (io_output_ready),
    .io_deq_valid       (_queue_io_deq_valid),
    .io_deq_bits_hartId (_queue_io_deq_bits_hartId),
    .io_deq_bits_instId (_queue_io_deq_bits_instId),
    .io_deq_bits_data   (_queue_io_deq_bits_data),
    .io_count           (_queue_io_count)
  );
  assign io_output_valid = _queue_io_deq_valid;
  assign io_output_bits_hartId = _queue_io_deq_valid ? _queue_io_deq_bits_hartId : 64'h0;
  assign io_output_bits_instId = _queue_io_deq_valid ? _queue_io_deq_bits_instId : 4'h0;
  assign io_output_bits_data = _queue_io_deq_valid ? _queue_io_deq_bits_data : 64'h0;
endmodule

