module VStoreSentinel(
  input  clock,
         reset,
         io_enq_valid,
         io_deq_valid,
  output io_hasStore
);

  reg  [7:0] counter;
  wire       both = io_enq_valid & io_deq_valid;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~both & ~io_enq_valid & io_deq_valid & ~reset & ~(|counter)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: Store Sentinel receives Deq when no store is in-flight!\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  always @(posedge clock) begin
    if (reset)
      counter <= 8'h0;
    else if (~both) begin
      if (io_enq_valid)
        counter <= counter + 8'h1;
      else if (io_deq_valid)
        counter <= counter - 8'h1;
    end
  end // always @(posedge)
  assign io_hasStore = |counter;
endmodule

